N = 1 << H
s = MerkleSigner(height=H, token_bytes=counter_tokens())
errors, used = [], []
lock = threading.Lock()
barrier = threading.Barrier(N)

def worker(i):
    try:
        barrier.wait(timeout=10)
        if i % 3 == 0:
            try:
                before, after = s.advance_to(s.next_index + 1)
                assert before <= after  # equal target legal (lost race)
            except ValueError:
                pass  # target read stale past N
        elif i % 3 == 1:
            try:
                sig = s.sign(f"m{i}")
                with lock:
                    used.append(sig.index)
            except KeyExhaustedError:
                pass
        else:
            # checkpoint/restore always yields a self-consistent state
            blob = s.checkpoint()
            saved = int.from_bytes(blob[11:13], "big")
            r = MerkleSigner.from_checkpoint(blob)
            assert r.next_index == saved and r.remaining == N - saved
    except Exception as exc:
        with lock:
            errors.append(exc)

ts = [threading.Thread(target=worker, args=(i,)) for i in range(N)]
for t in ts: t.start()
for t in ts: t.join()
assert errors == [], errors
assert len(used) == len(set(used))            # no leaf signed twice
assert s.next_index + s.remaining == N
assert s.next_index <= N
print("CONCURRENCY OK; final next_index =", s.next_index, "signed =", len(used))
